def contains_three_numerals(file_name):
    return sum(1 for char in file_name if char.isdigit()) <= 3

def has_one_period(file_name):
    return file_name.count('.') == 1

def starts_with_letter(file_name):
    return file_name.split('.')[0].strip().isalpha()

def valid_extension(file_name):
    return file_name.split('.')[-1] in ['txt', 'exe', 'dll']

def file_name_check(file_name):
    if contains_three_numerals(file_name) and has_one_period(file_name) and starts_with_letter(file_name) and valid_extension(file_name):
        return 'Yes'
    else:
        return 'No'

